"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["99945"],{69845(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.arredondamento_indevido","status":422,"titulo":"Arredondamento local n\xe3o se aplica quando a classifica\xe7\xe3o \xe9 importada"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.arredondamento_indevido","requisitos":[],"oQueAconteceu":["A regra de c\xe1lculo declarada \xe9 `CLASSIFICACAO_IMPORTADA` (a nota final vem\\npronta de outra origem \u2014 SiSU/ENEM), mas a configura\xe7\xe3o tamb\xe9m informou uma\\nregra de arredondamento (`regraArredondamentoCodigo`). As duas coisas s\xe3o\\nincoerentes: arredondamento \xe9 precis\xe3o de um c\xe1lculo feito localmente\\n(`FORMULA_MEDIA_PONDERADA`), e quando o c\xe1lculo \xe9 importado n\xe3o h\xe1 nota a\\narredondar \u2014 ela j\xe1 chegou pronta.","Esta \xe9 uma das confer\xeancias que a mesma configura\xe7\xe3o pode reprovar juntas\\nquando `CLASSIFICACAO_IMPORTADA` \xe9 declarada \u2014 as outras s\xe3o\\n[`casas_arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_indevido)\\n(a metade do par que fica com o campo `casasArredondamento`) e\\n[`eliminacao_indevida`](/erros/uniplus.selecao.configuracao_classificacao.eliminacao_indevida).\\nElas s\xe3o independentes entre si \u2014 cada uma dispara pelo pr\xf3prio campo \u2014, e\\nnenhuma delas coexiste com\\n[`arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_obrigatorio)\\nnem com\\n[`casas_arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_obrigatorio)\\n\u2014 s\xe3o o ramo oposto (c\xe1lculo local), mutuamente exclusivo com este.","J\xe1\\n[`eliminacao_enem_fora_de_processo_enem`](/erros/uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem)\\n**n\xe3o** \xe9 exclusiva de nenhum dos dois ramos \u2014 \xe9 conferida sempre, depois de\\nqualquer um deles. Uma configura\xe7\xe3o que reprova esta causa (`CLASSIFICACAO_IMPORTADA`\\ncom `regraArredondamentoCodigo` informado) e que tamb\xe9m declare regras de\\nelimina\xe7\xe3o pode reprovar as duas juntas, se essas regras n\xe3o tiverem amparo\\nem `baseadoEmEnem`; o mesmo vale do outro lado, para uma configura\xe7\xe3o local\\nque reprove\\n`arredondamento_obrigatorio`/`casas_arredondamento_obrigatorio`.","**Essa acumula\xe7\xe3o s\xf3 \xe9 observ\xe1vel no caminho de defini\xe7\xe3o** \u2014 \xe9 l\xe1 que a\\nresposta de fato pode trazer mais de um destes c\xf3digos juntos (ADR-0125)."],"comoResolver":["Remova `regraArredondamentoCodigo` (e `regraArredondamentoVersao`) da\\nconfigura\xe7\xe3o quando `regraCalculoCodigo` for `CLASSIFICACAO_IMPORTADA`. Se a\\ninten\xe7\xe3o era arredondar localmente, declare `FORMULA_MEDIA_PONDERADA` como\\nregra de c\xe1lculo."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);